window.kbPageData["views/entry/k-62f85243294247ab"] = {"key":"entry/k-62f85243294247ab","state":{"route":"entry/k-62f85243294247ab"},"node":{"id":"k-62f85243294247ab","mode":"k","title":"国务院《加快农业农村现代化“十五五”规划》（6 月）","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["rural"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"国务院《加快农业农村现代化“十五五”规划》（6 月）","slug":"943318d1f3b8"}],"directorySummary":"考点十五 国务院《加快农业农村现代化“十五五”规划》（6 月）\n规划强调以加快农业农村现代化更好推进中国式现代化建设，将因地制宜发展农业新质生产力\n摆在更加突出的战略位置，并首次提出培育壮大农业领域新兴产业和未来产业。明确“十五\n五”时期是基本实现农业农村现代化的关键时期，坚持农业农村优先发展、城乡…","sources":[{"id":"336a6f0485ec8ebd","label":"国务院《加快农业农村现代化“十五五”规划》（6 月）","topic":"重要文件","category":"时政","text":"考点十五 国务院《加快农业农村现代化“十五五”规划》（6 月）\n规划强调以加快农业农村现代化更好推进中国式现代化建设，将因地制宜发展农业新质生产力\n摆在更加突出的战略位置，并首次提出培育壮大农业领域新兴产业和未来产业。明确“十五\n五”时期是基本实现农业农村现代化的关键时期，坚持农业农村优先发展、城乡融合发展，锚\n定建设农业强国目标，以推进乡村全面振兴为总抓手，以学习运用“千万工程”经验为引领，\n统筹发展科技农业、绿色农业、质量农业、品牌农业。到 2030 年，农业科技进步贡献率达到\n67%；到 2035 年，乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生\n活条件，农业强国建设取得显著成效。","source":{"doc":"4e539a366dce19555ccf","first":15,"last":15,"page":15,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-62f85243294247ab":[]}};
